
.poll-modal {
	position: relative;
	padding: calc(3 * var(--default-grid-baseline));

	&__capture-area {
		padding: calc(4 * var(--default-grid-baseline));
		background-color: var(--color-main-background);
	}

	&__header {
		display: flex;
		align-items: flex-start;
		gap: 8px;
		margin-block: 8px;
		font-weight: bold;
		font-size: 18px;
		white-space: normal;
		overflow-wrap: anywhere;

		&-wrapper {
			margin-inline-start: calc( (3 / 2) * var(--default-grid-baseline));
		}
	}

	&__summary {
		color: var(--color-text-maxcontrast);
		margin-bottom: 16px;

		&-details {
			display: flex;
			align-items: center;
			gap: var(--default-grid-baseline);
		}
	}

	&__options {
		display: flex;
		flex-direction: column;
		gap: 4px;
		overflow-wrap: anywhere;
	}

	&__actions {
		position: sticky;
		bottom: 0;
		display: flex;
		flex-wrap: wrap;
		gap: 8px;
		padding: 8px 0 0;
		background-color: var(--color-main-background);
		justify-content: end;
	}

	&__loading {
		height: 200px;
	}

	&__status {
		display: flex;
		flex-direction: row;
		gap: var(--default-grid-baseline);
	}
}

.results__options {
	display: flex;
	flex-direction: column;
	gap: calc(4 * var(--default-grid-baseline));
	overflow-wrap: anywhere;
	margin: 8px 0 20px 0;
}

.results__option {
	display: flex;
	flex-direction: column;
	padding: var(--default-grid-baseline);
	border-radius: var(--border-radius-large);

	&:hover {
		background-color: var(--color-background-hover);
	}

	&__details {
		display: flex;
		margin-bottom: 8px;
	}

	&-subtitle {
		display: flex;
		gap: var(--default-grid-baseline);
		color: var(--color-text-maxcontrast);
	}

	&-progress {
		margin-top: 4px;
	}

	&-title {
		display: flex;
		justify-content: space-between;
		align-items: flex-start;
		margin-bottom: 4px;

		.percentage {
			white-space: nowrap;
			margin-inline-start: 16px;
		}
	}
}

.critical :deep(.action-button) {
	color: var(--color-text-error) !important;
}
