
.screenContainer {
	width: 100%;
	height: 100%;
}

.screen {
	width: 100%;
	height: 100%;
	position: absolute;
	top: 0;
	inset-inline-start: 0;
	&--fit {
		object-fit: contain;
	}
	&--fill {
		object-fit: cover;
	}
	&--magnify {
		cursor: zoom-in;
	}
	&--grab {
		cursor: grab;
	}
	&--grabbing {
		cursor: grabbing;
	}
}

.screen-placeholder {
	width: 100%;
	height: 100%;
	position: absolute;
	inset: 0;
	color: var(--color-main-text);
	background-color: rgba(var(--color-main-background-rgb), 0.95);

	&__actions {
		display: flex;
		gap: var(--default-grid-baseline);
	}
}

